@Component("advertiser-handler")
@ProcessingGroup("advertiser-processing-group")
public class AdvertiserEventHandler {
	
	// core constructor
	AdvertiserEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateAdvertiserEvent
     */
    @EventHandler
    public void handle( CreateAdvertiserEvent event) {
        entityManager.persist(new Advertiser(event.getAdvertiserId(), event.getName(), event.getLegalName(), event.getIndustry(), event.getWebsite(), event.getAgency(), event.getAdAccounts(), event.getBillingProfiles(), event.getCampaigns(), event.getTrackingPixels()));
    }

    /*
     * @param	event UpdateAdvertiserEvent
     */
    @EventHandler
    public Advertiser handle( UpdateAdvertiserEvent event) {
    	entityManager.merge(new Advertiser(event.getAdvertiserId(), event.getName(), event.getLegalName(), event.getIndustry(), event.getWebsite(), event.getAgency(), event.getAdAccounts(), event.getBillingProfiles(), event.getCampaigns(), event.getTrackingPixels()));
    }
    
    /*
     * @param	event DeleteAdvertiserEvent
     */
    @EventHandler
    public void on( DeleteAdvertiserEvent event) {
    	Advertiser entity = new Advertiser();
   
    	// ------------------------------------------
    	// apply the AdvertiserId
    	// ------------------------------------------
    	entity.setAdvertiserId( event.getAdvertiserId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final AdvertiserRepository advertiserEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(AdvertiserEventHandler.class.getName());

}
